CREATE TABLE "income_tax_years" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "income_tax_years_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" uuid DEFAULT app.uid() NOT NULL,
	"year" integer NOT NULL,
	"rate" integer NOT NULL,
	"known_amount" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "income_tax_years_user_id_id_unique" UNIQUE("user_id","id"),
	CONSTRAINT "income_tax_years_user_year_unique" UNIQUE("user_id","year"),
	CONSTRAINT "income_tax_years_year_check" CHECK ("income_tax_years"."year" between 2000 and 2100),
	CONSTRAINT "income_tax_years_rate_check" CHECK ("income_tax_years"."rate" between 0 and 6000),
	CONSTRAINT "income_tax_years_known_amount_check" CHECK ("income_tax_years"."known_amount" is null or "income_tax_years"."known_amount" between 0 and 1000000000000)
);
