-- The income tax reserve (a rate per tax year, the real amount later, and which tax office payments were income tax).
-- Hand-written additions to what drizzle-kit made. Nothing is seeded: every account starts with no tax years, so the
-- reserve does nothing until the person types a rate.

-- Same access as every other table: only the app role, only a user's own rows.
GRANT SELECT, INSERT, UPDATE, DELETE ON "income_tax_years" TO kasboek_app;
--> statement-breakpoint
GRANT USAGE, SELECT ON SEQUENCE "income_tax_years_id_seq" TO kasboek_app;
--> statement-breakpoint
CREATE POLICY tenant ON "income_tax_years" FOR ALL TO kasboek_app USING (user_id = (SELECT app.uid())) WITH CHECK (user_id = (SELECT app.uid()));
--> statement-breakpoint

-- Supabase hands new tables to its API roles by default; take it away again (see 0002).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "income_tax_years" FROM anon, authenticated;
    REVOKE ALL ON SEQUENCE "income_tax_years_id_seq" FROM anon, authenticated;
  END IF;
END
$$;
